// Summarize returns a human-readable line describing whether s passed
// validation. It calls validate.Validate, giving cross-file, cross-package
// reference resolution something concrete to find within the Go fixture.
func Summarize(s string) string {
	if validate.Validate(s) {
		return "ok: " + s
	}
	return "invalid: " + s
}

// Validate reports whether s is a non-empty, trimmed string.
//
// It exists in this fixture specifically to collide in name with
// src/validate.ts's exported Validate: the ambiguous symbol that
// edge-resolution tests use to prove name-based matching stays intra-language
// and does not merge the Go and TypeScript hits together.
func Validate(s string) bool {
	return strings.TrimSpace(s) != ""
}

def is_even(n: int) -> bool:
    """Return True if n is even, deferring to is_odd for the recursive case."""
    if n == 0:
        return True
    return is_odd(n - 1)

def is_odd(n: int) -> bool:
    """Return True if n is odd, deferring to is_even for the recursive case."""
    if n == 0:
        return False
    return is_even(n - 1)

/**
 * summarize renders a validation result for value, calling Validate.
 * Exercises cross-file reference resolution within the TypeScript fixture.
 */
export function summarize(value: string): string {
  return Validate(value) ? `ok: ${value}` : `invalid: ${value}`;
}

/**
 * Validate reports whether the given value is a non-empty, trimmed string.
 *
 * This is the fixture's ambiguous symbol: a TypeScript export named Validate
 * that collides in name with pkg/validate/validate.go's Go export Validate,
 * proving that name-based edge resolution must not merge cross-language
 * hits.
 */
export function Validate(value: string): boolean {
  return value.trim().length > 0;
}
